mapper.select:
SELECT c.id, c.user_id userId, u.actual_name userName, c.file_md5 fileMd5, c.file_name fileName, c.file_url fileUrl, c.is_dir isDir, c.is_valid isValid, a.share_status shareStatus, a.share_batch_num shareBatchNum, a.share_type shareType, a.extraction_code extractionCode, c.file_size fileSize, c.file_path filePath, c.extend_name extendName, a.share_time shareTime, c.delete_time deleteTime, a.end_time endTime, c.delete_batch_num deleteBatchNum FROM t_wp_share a LEFT JOIN t_wp_share_file b ON b.share_batch_num = a.share_batch_num LEFT JOIN t_wp_user_file c ON c.id = b.file_id LEFT JOIN t_base_user u ON b.user_id = u.id WHERE a.is_valid =1 and u.is_valid =1 and c.is_valid =1
AND EXISTS ( select 1 from t_wp_user_file_label ufl where ufl.file_id = c.id and ufl.is_valid = 1 AND ufl.label_id IN
#{item}
)
and c.create_time >= #{query.startTime} and c.create_time <= #{query.endTime}
and c.user_id = #{query.userId}
AND (u.actual_name like #{likeName} or c.file_name like #{likeName})
order BY a.share_time desc
